head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > P > trim]<br/>입력값을 확정할때 앞뒤 공백을 제거할지 설정합니다.",
    "validation" : [
        "미설정 시 입력값을 확정할때 앞뒤 공백을 제거하지 않습니다.",
        "true 설정 시 입력값을 확정할때 앞뒤 공백을 제거합니다.",
        "false 설정 시 입력값을 확정할때 앞뒤 공백을 제거하지 않습니다.",                
        "일반적으로 Enter 키 입력 또는 포커스 해제 시 입력값이 확정되며 공백이 제거됩니다.",
        "DataCollection 에 바인딩 된 경우 데이터가 컴포넌트에 반영될때 공백이 제거됩니다.",
        "입력값을 붙여넣는 경우 dataType, allowChar, maxlength 등의 속성으로 입력값이 정리된 후 입력값이 확정될때 공백이 제거됩니다.",
        "setValue() 메소드를 통해 입력값이 설정될 때에도 공백이 제거됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text = function(target) {    
    let rtn = '';
    let tagName = target.render.tagName

    if (tagName !== "INPUT") {
        rtn = target.render.textContent
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);    
    }
    else {
        rtn = target.render.value
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);   
    }    
}



// target1
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("  123456  ");
    target1.focus();
};

scwin.btn_getText1_onclick = function (e) {
    scwin.get_text(target1);
}

